const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
let data={tasks:[],sessions:[],rules:[]},rev={},today=null;
const $=id=>document.getElementById(id);
function say(t,err){const s=$('status');s.textContent=t;s.className='status '+(err?'err':'ok');}
function wd(s){return new Date(s+'T00:00:00Z').getUTCDay();}
function addDays(s,n){const d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function nice(s){const d=new Date(s+'T00:00:00Z');return DAYS[d.getUTCDay()]+', '+s;}
function blocked(extra){const b=new Set(data.rules.map(r=>r.day));if(extra!==undefined)b.add(extra);return b;}
function allowed(b){const l=[];for(let i=0;i<14;i++){const d=addDays(today,i);if(!b.has(wd(d)))l.push(d);}return l;}
function rv(c,id){return (rev[c]&&rev[c][id])||1;}
async function load(){const r=await tessera.call('data.read',{});const d=r.data;data={tasks:d.tasks||[],sessions:d.sessions||[],rules:d.rules||[]};rev=r.revisions||{};render();}
function render(){
 const rl=$('rules');rl.textContent='';
 if(!data.rules.length){const li=document.createElement('li');li.textContent='No rules: every evening is open.';rl.appendChild(li);}
 for(const r of data.rules){const li=document.createElement('li');li.setAttribute('data-hook','rule');const sp=document.createElement('span');sp.textContent='No sessions on '+DAYS[r.day]+'s';const b=document.createElement('button');b.type='button';b.className='sec';b.setAttribute('data-hook','rule-remove');b.textContent='Remove rule';b.setAttribute('aria-label','Remove rule: no sessions on '+DAYS[r.day]+'s');b.addEventListener('click',()=>removeRule(r));li.append(sp,b);rl.appendChild(li);}
 const names={};for(const t of data.tasks)names[t.id]=t.name;
 const byDate={};for(const s of data.sessions){if(!names[s.taskId])continue;(byDate[s.date]=byDate[s.date]||[]).push(s);}
 const plan=$('plan');plan.textContent='';
 $('empty').hidden=data.tasks.length>0;
 for(const d of Object.keys(byDate).sort()){const box=document.createElement('div');box.className='day';const h=document.createElement('h3');h.textContent=nice(d)+' (evening)';box.appendChild(h);
 for(const s of byDate[d]){const p=document.createElement('div');p.className='s';p.setAttribute('data-hook','session');const t=document.createElement('time');t.setAttribute('datetime',d);t.textContent=d;const n=document.createElement('span');n.setAttribute('data-hook','session-task');n.textContent=names[s.taskId];p.append(t,n);box.appendChild(p);}
 plan.appendChild(box);}
 const tl=$('topics');tl.textContent='';
 if(!data.tasks.length){const li=document.createElement('li');li.textContent='Nothing here yet.';tl.appendChild(li);}
 for(const t of data.tasks){const li=document.createElement('li');const sp=document.createElement('span');const c=data.sessions.filter(s=>s.taskId===t.id).length;sp.textContent=t.name+' - '+c+(c===1?' session':' sessions');const b=document.createElement('button');b.type='button';b.className='sec';b.textContent='Delete';b.setAttribute('aria-label','Delete topic '+t.name+' and its sessions');b.addEventListener('click',()=>delTask(t));li.append(sp,b);tl.appendChild(li);}
}
async function patch(ops){return tessera.call('data.patch',{operations:ops});}
async function addTask(){
 const inp=$('tn');const name=inp.value.trim();
 if(!name){say('Type a topic name first.',true);inp.focus();return;}
 const L=allowed(blocked());
 if(!L.length){say('Every weekday is ruled out, so there is no evening to study. Remove a rule first.',true);return;}
 const count=Math.min(3,L.length);const base=data.tasks.length%Math.max(1,Math.floor(L.length/count));
 const pick=new Set();for(let k=0;k<count;k++)pick.add(L[(base+Math.floor(k*L.length/count))%L.length]);
 const ops=[{op:'add',collection:'tasks',record:{name}}];
 try{
  const r=await patch(ops);const id=r.addedIds[0];
  await patch([...pick].map(d=>({op:'add',collection:'sessions',record:{taskId:id,date:d}})));
  inp.value='';await load();say('Added "'+name+'" with '+pick.size+(pick.size===1?' session.':' sessions.'));
 }catch(e){say('Could not add the topic. Please try again.',true);await load();}
}
async function addRule(){
 const day=Number($('rd').value);
 if(data.rules.some(r=>r.day===day)){say('There is already a rule for '+DAYS[day]+'.',true);return;}
 const b=blocked(day);
 if(b.size>=7){say('You can\'t rule out every weekday.',true);return;}
 const L=allowed(b);const load0={};for(const s of data.sessions)load0[s.date]=(load0[s.date]||0)+1;
 const have={};for(const s of data.sessions){if(!b.has(wd(s.date)))(have[s.taskId]=have[s.taskId]||new Set()).add(s.date);}
 const ops=[{op:'add',collection:'rules',record:{day}}];let moved=0;
 for(const s of data.sessions){if(wd(s.date)!==day)continue;
  const used=have[s.taskId]=have[s.taskId]||new Set();
  const cand=L.filter(d=>!used.has(d));
  if(!cand.length){ if(used.size>0){ops.push({op:'remove',collection:'sessions',id:s.id,revisionCount:rv('sessions',s.id)});continue;} }
  let best=null,bs=1e9;for(const d of cand){const dist=Math.abs((new Date(d)-new Date(s.date))/864e5);const sc=(load0[d]||0)*100+dist;if(sc<bs){bs=sc;best=d;}}
  if(best===null)continue;
  used.add(best);load0[best]=(load0[best]||0)+1;moved++;
  ops.push({op:'replace',collection:'sessions',id:s.id,revisionCount:rv('sessions',s.id),fields:{date:best}});}
 try{await patch(ops);await load();say('Rule added. '+moved+(moved===1?' session moved':' sessions moved')+' to other days.');}
 catch(e){say('Could not add the rule. Please try again.',true);await load();}
}
async function removeRule(r){
 try{await patch([{op:'remove',collection:'rules',id:r.id,revisionCount:rv('rules',r.id)}]);await load();say('Rule removed. Existing sessions stay where they are; new topics may use '+DAYS[r.day]+'s.');$('rd').focus();}
 catch(e){say('Could not remove the rule.',true);await load();}
}
async function delTask(t){
 if(!confirm('Delete "'+t.name+'" and all its sessions?'))return;
 const ops=data.sessions.filter(s=>s.taskId===t.id).map(s=>({op:'remove',collection:'sessions',id:s.id,revisionCount:rv('sessions',s.id)}));
 ops.push({op:'remove',collection:'tasks',id:t.id,revisionCount:rv('tasks',t.id)});
 try{await patch(ops);await load();say('Deleted "'+t.name+'".');$('tn').focus();}
 catch(e){say('Could not delete the topic.',true);await load();}
}
$('ta').addEventListener('click',addTask);
$('tn').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addTask();}});
$('ra').addEventListener('click',addRule);
(async()=>{try{const c=await tessera.call('clock.now',{});today=c.date;await load();}catch(e){say('Could not load your plan.',true);}})();

