const notes=document.getElementById('notes');
const msg=document.getElementById('msg');
const list=document.getElementById('list');
const empty=document.getElementById('empty');
const count=document.getElementById('count');
const btn=document.getElementById('make');
function say(t,k){msg.textContent=t;msg.className=k||'';}
function render(cards){
  list.textContent='';
  empty.hidden=cards.length>0;
  count.textContent=cards.length?'('+cards.length+')':'';
  for(const c of cards){
    const li=document.createElement('li');
    li.setAttribute('data-hook','card');
    const f=document.createElement('div');
    f.className='front';f.setAttribute('data-hook','card-front');f.textContent=c.front;
    const b=document.createElement('div');
    b.className='back';b.setAttribute('data-hook','card-back');b.textContent=c.back;
    li.appendChild(f);li.appendChild(b);list.appendChild(li);
  }
}
async function load(){
  try{
    const r=await tessera.call('data.read',{});
    render(Array.isArray(r.data.cards)?r.data.cards:[]);
  }catch(e){say('The cards could not be loaded. Try reopening the tool.','error');}
}
btn.addEventListener('click',async()=>{
  const ops=[];
  for(const line of notes.value.split(/\r?\n/)){
    const i=line.indexOf(':');
    if(i<0)continue;
    const front=line.slice(0,i).trim();
    const back=line.slice(i+1).trim();
    if(front&&back)ops.push({op:'add',collection:'cards',record:{front:front,back:back}});
  }
  if(!ops.length){say('No cards made. Write each line as front: back.','error');return;}
  btn.disabled=true;
  try{
    await tessera.call('data.patch',{operations:ops});
    notes.value='';
    say(ops.length+(ops.length===1?' card':' cards')+' made and saved.','ok');
    await load();
  }catch(e){say('The cards could not be saved. Your notes are still here; try again.','error');}
  btn.disabled=false;
});
load();
